const articles = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const article of results) {
    articles.push({
      title: article.title,
      url: article.url,
      summary: (article.content || "").substring(0, 300),
    });
  }
}

return [
  {
    json: {
      articles,
    },
  },
];

// One item per post: context (label+source, no button), post (EXACT LinkedIn text),
// imagePrompt (for Gemini image gen).
const order = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5 };
const posts = ($input.first().json.output && $input.first().json.output.posts) || [];
const sorted = [...posts].sort((a, b) => {
  const da = order[String(a.day || '').toLowerCase()] || 99;
  const db = order[String(b.day || '').toLowerCase()] || 99;
  return da - db || (Number(a.option) || 0) - (Number(b.option) || 0);
});
return sorted.map((p) => {
  const day = String(p.day || '').toUpperCase();
  const opt = p.option != null ? p.option : '?';
  const dev = Array.isArray(p.development) ? p.development : (p.development ? [p.development] : []);
  const devLines = dev.map((l) => {
    const t = String(l).trim();
    return /^(→|•|-|\*)/.test(t) ? t : '→ ' + t;
  }).join('\n');
  const tags = Array.isArray(p.hashtags) ? p.hashtags.join(' ') : (p.hashtags || '');
  const post = [p.hook, '', devLines, '', p.insight, '', p.question, '', tags]
    .join('\n').replace(/\n{3,}/g, '\n\n').trim();
  const context = `📅 ${day} — Option ${opt} of 3\nSource: ${p.source_title || ''} — ${p.source_url || ''}`;
  const imagePrompt =
    'Professional, modern, editorial LinkedIn hero visual for an enterprise-technology ' +
    'thought-leadership post. Topic: ' + (p.source_title || day) + '. Themes: enterprise AI, ' +
    'SAP S/4HANA, HR technology, African enterprise digital transformation. Clean corporate ' +
    'aesthetic, abstract, cinematic lighting, blue and slate palette, high quality. ' +
    'Absolutely NO text, NO words, NO letters, NO numbers, NO logos in the image.';
  return { json: { day, option: p.option, context, post, imagePrompt } };
});

// Pull base64 image from the Gemini generateContent response; build the photo caption.
const resp = $input.first().json || {};
const parts = (resp.candidates && resp.candidates[0] && resp.candidates[0].content
  && resp.candidates[0].content.parts) || [];
let b64 = '', mime = 'image/png';
for (const part of parts) {
  const inl = part.inlineData || part.inline_data;
  if (inl && inl.data) { b64 = inl.data; mime = inl.mimeType || inl.mime_type || mime; break; }
}
if (!b64) {
  throw new Error('Gemini returned no image. Response: ' + JSON.stringify(resp).slice(0, 500));
}

// FALLBACK for Telegram's 1024-char caption limit: truncate-to-fit at a line/word
// boundary so the caption stays IDENTICAL to what the listener posts to LinkedIn.
let caption = String($('Loop Over Posts').item.json.post || '');
if (caption.length > 1024) {
  caption = caption.slice(0, 1020);
  const cut = Math.max(caption.lastIndexOf('\n'), caption.lastIndexOf(' '));
  if (cut > 800) caption = caption.slice(0, cut);
  caption = caption.trim() + '…';
}

const ext = /jpe?g/.test(mime) ? 'jpg' : (/webp/.test(mime) ? 'webp' : 'png');
return [{ json: { imageB64: b64, mime, ext, caption } }];
